package com.ecommerce.order;

import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderPlacementService {

    private final OrderRepository orderRepository;
    private final KafkaTemplate<String, Object> kafkaTemplate;

    public OrderPlacementService(OrderRepository orderRepository, KafkaTemplate<String, Object> kafkaTemplate) {
        this.orderRepository = orderRepository;
        this.kafkaTemplate = kafkaTemplate;
    }

    @Transactional
    public OrderResponse createOrder(CreateOrderRequest request) {
        Order order = Order.from(request);
        order.setStatus(OrderStatus.PENDING_PAYMENT);
        orderRepository.save(order);

        // Outbox pattern or direct event publishing for Saga orchestration
        OrderCreatedEvent event = new OrderCreatedEvent(order.getId(), order.getCustomerId(), order.getItems());
        kafkaTemplate.send("order-created-topic", order.getId().toString(), event);

        return new OrderResponse(order.getId(), order.getStatus());
    }
}
